{
  "project_id": "9e3240a17b4743208f32",
  "query": "select pg_size_pretty(pg_database_size(current_database())) as database_size;
select schemaname, relname as table_name, n_live_tup, n_dead_tup, pg_size_pretty(pg_total_relation_size(relid)) as total_size
from pg_stat_user_tables
order by pg_total_relation_size(relid) desc
limit 20;"
}

